import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.kcd3e0J6.js";const d="/study/images/browser/audio-occlusion-path.svg",i="/study/images/browser/audio-occlusion-response.svg",p=JSON.parse('{"title":"Web Audioの音の遮蔽 — 壁越しの音量と音色","description":"","frontmatter":{"title":"Web Audioの音の遮蔽 — 壁越しの音量と音色","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"聞き手と音源の間に壁があるかを調べ、ゲインとローパスフィルターで直接音の弱まり方を変える。","aliases":["Web Audio API","音の遮蔽","occlusion","レイキャスト","ローパスフィルター","lowpass","BiquadFilterNode","GainNode","カットオフ","周波数応答"],"verification":"W3C Web Audio APIのフィルターとゲインの仕様、Unreal Engine公式ドキュメントの遮蔽機能に照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-occlusion.md","filePath":"browser/audio-occlusion.md"}'),n={name:"browser/audio-occlusion.md"};function s(l,e,c,u,h,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="web-audioの音の遮蔽-—-壁越しの音量と音色" tabindex="-1">Web Audioの音の遮蔽 — 壁越しの音量と音色 <a class="header-anchor" href="#web-audioの音の遮蔽-—-壁越しの音量と音色" aria-label="Permalink to &quot;Web Audioの音の遮蔽 — 壁越しの音量と音色&quot;">​</a></h1><p>壁の向こうの足音は、同じ距離にある足音でも小さく、こもって聞こえることがあります。ゲームでこの違いを表すには、聞き手と音源の間に壁があるかを調べ、音量と周波数ごとの強さを変えます。Unreal Engineの遮蔽機能にも、障害物を調べる設定と、遮蔽時のゲインやローパスフィルターを決める設定があります。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/sound-attenuation-in-unreal-engine#attenuationocclusion" target="_blank" rel="noreferrer">Unreal Engineの音の減衰と遮蔽</a></p><h2 id="直接届く経路に壁があるか調べる" tabindex="-1">直接届く経路に壁があるか調べる <a class="header-anchor" href="#直接届く経路に壁があるか調べる" aria-label="Permalink to &quot;直接届く経路に壁があるか調べる&quot;">​</a></h2><p>聞き手から音源に向かってレイキャストし、音源までの区間で壁などに当たるかを調べます。描画用の形と遮蔽判定用の形を分ける場合は、閉じた扉など、音を遮るものが判定に含まれるようにします。<a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/sound-attenuation-in-unreal-engine#occlusiontracechannel" target="_blank" rel="noreferrer">Unreal Engineの遮蔽判定に使うトレース</a></p><p>実践では、聞き手を <code>(x, z) = (0, 0)</code>、壁を <code>z = −2.5</code> の <code>x = −2〜2</code> に置きます。聞き手と音源を結ぶ線分が <code>z = −2.5</code> に達したとき、そこでの <code>x</code> が壁の範囲に入れば遮蔽です。真っすぐ先の音源 <code>(0, −6)</code> への線分は <code>x = 0</code> で壁に当たり、右前の音源 <code>(4.8, −3.6)</code> への線分は <code>x ≈ 3.33</code> で壁の右を通ります。どちらも聞き手からの距離は6です。</p><figure class="study-figure"><img src="'+d+'" alt="上から見た聞き手と壁と二つの音源。聞き手から真っすぐ先の音源への線分は壁に当たり、右前の音源への線分は壁の右を通る。どちらの音源も聞き手からの距離は6。" width="760" height="416" loading="lazy"><figcaption>距離が同じでも、音源との間に壁があるかどうかで遮蔽の判定が変わります。<a href="/study/images/browser/audio-occlusion-path.svg" target="_blank" rel="noopener noreferrer">遮蔽判定の図を拡大</a></figcaption></figure><h2 id="全体を小さくする処理と高音を弱める処理" tabindex="-1">全体を小さくする処理と高音を弱める処理 <a class="header-anchor" href="#全体を小さくする処理と高音を弱める処理" aria-label="Permalink to &quot;全体を小さくする処理と高音を弱める処理&quot;">​</a></h2><p><code>GainNode</code> のゲインを0.5にすると、すべての周波数成分の振幅が半分になります。振幅比を <code>20 × log10(振幅比)</code> で表すと約−6.02 dBです。そこに <code>BiquadFilterNode</code> の <code>lowpass</code> を重ねると、カットオフ周波数付近から周波数が上がるにつれて振幅が徐々に弱まり、音色も変わります。<a href="https://www.w3.org/TR/webaudio/#GainNode" target="_blank" rel="noreferrer">W3C Web Audio APIのGainNode</a> · <a href="https://www.w3.org/TR/webaudio/#BiquadFilterNode" target="_blank" rel="noreferrer">BiquadFilterNode</a></p><p>実践では、サンプルレート48,000 Hz、カットオフ1,000 Hzの2次ローパスを使います。この型の <code>Q</code> はdBで指定するため、カットオフでフィルター単体の振幅比が <code>1 / √2</code> になる設定では <code>Q ≈ −3.0103</code> です。ゲインとフィルターを直列につなぐと各周波数の振幅比が掛け合わされるので、dBで表した増減は足し算できます。<a href="https://www.w3.org/TR/webaudio/#BiquadFilterNode" target="_blank" rel="noreferrer">W3C Web Audio APIのBiquadFilterNodeと係数</a></p><table tabindex="0"><thead><tr><th>処理</th><th style="text-align:right;">250 Hzの振幅の増減</th><th style="text-align:right;">4,000 Hzの振幅の増減</th></tr></thead><tbody><tr><td>遮蔽なし</td><td style="text-align:right;">0 dB</td><td style="text-align:right;">0 dB</td></tr><tr><td>ゲイン0.5</td><td style="text-align:right;">−6.02 dB</td><td style="text-align:right;">−6.02 dB</td></tr><tr><td>ゲイン0.5とローパス</td><td style="text-align:right;">約−6.04 dB</td><td style="text-align:right;">約−30.50 dB</td></tr></tbody></table><figure class="study-figure"><img src="'+i+'" alt="遮蔽なしは全周波数で0 dB。ゲイン0.5は全周波数で約マイナス6.02 dB。ゲイン0.5にカットオフ1,000 Hzのローパスを重ねると、250 Hzで約マイナス6.04 dB、4,000 Hzで約マイナス30.50 dBになる。" width="760" height="416" loading="lazy"><figcaption>ゲインだけを変えると曲線は水平です。ローパスを加えると、高い周波数ほど大きく弱まります。<a href="/study/images/browser/audio-occlusion-response.svg" target="_blank" rel="noopener noreferrer">周波数応答の図を拡大</a></figcaption></figure><h2 id="ゲームでは遮蔽と音の位置を別々に更新する" tabindex="-1">ゲームでは遮蔽と音の位置を別々に更新する <a class="header-anchor" href="#ゲームでは遮蔽と音の位置を別々に更新する" aria-label="Permalink to &quot;ゲームでは遮蔽と音の位置を別々に更新する&quot;">​</a></h2><p>モノラルの効果音なら、音源ごとにゲインとフィルターで遮蔽を表し、<code>PannerNode</code> で方向と距離を反映できます。再生中に扉が開閉するときは、ゲインとカットオフ周波数を <code>AudioParam.setTargetAtTime()</code> などで新しい値に近づけると、音量や音色が急に変わるのを抑えられます。壁の端で判定が頻繁に切り替わる場合は、少し時間を置いて状態を確定する方法もあります。<a href="/study/browser/audio-spatial-panning.html">Web Audioの音の定位と距離減衰</a> · <a href="https://www.w3.org/TR/webaudio/#AudioParam" target="_blank" rel="noreferrer">W3C Web Audio APIのAudioParam</a></p><p>壁を挟んだときも、扉や廊下を通る音、壁に反射した音などが聞き手に届く場合があります。線分1本のモデルは直接経路の判定に使い、ほかの経路の強さは必要に応じて別に調整します。ゲイン0.5やカットオフ1,000 Hzはこの実験の設定です。実際の聞こえ方は壁の材質や厚さ、周囲の形にも左右されます。<a href="/study/browser/audio-convolution-reverb.html">Web Audioの畳み込みリバーブ</a></p><h2 id="ブラウザで同じ音を聴き比べる" tabindex="-1">ブラウザで同じ音を聴き比べる <a class="header-anchor" href="#ブラウザで同じ音を聴き比べる" aria-label="Permalink to &quot;ブラウザで同じ音を聴き比べる&quot;">​</a></h2><p>実践では、同じ距離の二つの位置を切り替え、壁の判定とフィルターの効果を比べます。<code>getFrequencyResponse()</code> でローパスの振幅比を求め、ゲインと合わせた結果をグラフにします。壁に当たる位置を選び、同じ音を「ゲインのみ」と「ゲイン＋ローパス」で聴き比べると、音量の変化と高音の弱まりを確認できます。<a href="/study/practice/browser/audio-occlusion-observation.html">音の遮蔽の実践</a> · <a href="https://www.w3.org/TR/webaudio/#BiquadFilterNode-methods" target="_blank" rel="noreferrer">W3C Web Audio APIの周波数応答</a></p><p>扉が開いたときのように、再生中に遮蔽が切り替わる場合は、ゲインとカットオフを短い時間で新しい値へ近づけられます。<a href="/study/browser/audio-occlusion-transition.html">Web Audioで遮蔽をなめらかに切り替える</a></p>',17)])])}const f=t(n,[["render",s]]);export{p as __pageData,f as default};
